let db;try{db=JSON.parse(localStorage.getItem(STORE))||structuredClone(seed)}catch{db=structuredClone(seed)}
let state={page:'overview',role:'Manager',branch:branches[0],patient:'SFC-001',date:TODAY,doctor:doctors[0],inventoryBranch:branches[0],stockTab:'stock',billingTab:'invoices',month:'2026-10',loggedIn:true,portal:false};
const permissions={Manager:['overview','patients','appointments','pharmacy','billing','reports'],Receptionist:['overview','patients','appointments','billing'],Doctor:['overview','patients','appointments'], 'Pharmacy assistant':['overview','pharmacy']};
