const money=n=>'RM '+Number(n).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
const total=i=>i.items.reduce((s,x)=>s+x.qty*x.price,0);
const patient=id=>db.patients.find(p=>p.id===id);
const initials=name=>name.replace(/^Dr\.\s*/,'').split(' ').slice(0,2).map(x=>x[0]).join('');
const dateLabel=s=>!s?'To be completed':new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const nextId=(prefix,list,key='id')=>prefix+String(Math.max(0,...list.map(x=>Number(x[key].replace(/\D/g,''))))+1).padStart(3,'0');
function persist(){try{localStorage.setItem(STORE,JSON.stringify(db))}catch{toast('Changes will remain available for this session only.')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function badge(status){let cls=/Paid|Checked in|Received|Approved|Available|Saved/.test(status)?'green':/Low stock|Rejected|Unpaid|Expiring/.test(status)?'red':/Pending|Submitted|In consultation/.test(status)?'amber':'';return `<span class="tag ${cls}">${esc(status)}</span>`}
const option=(values,selected)=>values.map(v=>`<option ${v===selected?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');
const person=p=>`<div class="patient-cell"><span class="avatar">${esc(initials(p.name))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.id)}</small></div></div>`;
function nav(page){if(!permissions[state.role].includes(page)){toast('This screen is available to another staff role.');return}state.page=page;state.portal=false;closeModal();render();window.scrollTo(0,0)}
function render(){if(state.portal){renderPortal();return}if(!state.loggedIn){renderLogin();return}if(!permissions[state.role].includes(state.page))state.page='overview';const labels={overview:'Overview',patients:'Patients',appointments:'Appointments',pharmacy:'Pharmacy',billing:'Billing & claims',reports:'Reports'};const navIcons={overview:'grid',patients:'users',appointments:'calendar',pharmacy:'pill',billing:'receipt',reports:'chart'};$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" aria-label="Main navigation"><div class="brand"><img src="assets/logo.svg" alt="SFC temporary logo"><div><strong>Sunrise</strong><small>Family Clinics</small></div></div><div class="nav-label">WORKSPACE</div><nav>${permissions[state.role].map(k=>`<button class="nav-btn ${state.page===k?'active':''}" data-nav="${k}" ${state.page===k?'aria-current="page"':''}>${ic(navIcons[k])}${labels[k]}${k==='pharmacy'?`<span class="count">${db.stock.filter(m=>m.qty[branches.indexOf(state.branch)]<m.min).length+db.stock.filter(m=>m.expiry<="2026-11-18").length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><button class="portal-link" data-action="portal">${ic('calendar')}Patient booking portal ${ic('arrow')}</button><div class="side-note"><strong>CAREBRIDGE TECHNOLOGIES</strong><br>Connected care. Every branch.<br><span>Assignment prototype · Sample data</span></div></div></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation">${ic('menu')}</button><div class="breadcrumb">Workspace <span style="padding:0 10px">/</span> <strong>${labels[state.page]}</strong></div><div class="top-right"><span class="tag">${ic('lock')} Staff workspace</span><label class="sr-only" for="branch">Current branch</label><select id="branch" class="branch-select">${option(branches,state.branch)}</select><div class="top-actions"><button class="user-button" data-action="session" aria-label="Change staff role or sign out"><span class="avatar">${initials(roleNames[state.role])}</span><span class="user-text"><strong>${roleNames[state.role]}</strong><small>${state.role}</small></span></button></div></div></header><div class="content" id="content"></div></main></div>`;({overview:renderOverview,patients:renderPatients,appointments:renderAppointments,pharmacy:renderPharmacy,billing:renderBilling,reports:renderReports})[state.page]();$('#branch').onchange=e=>{state.branch=e.target.value;state.inventoryBranch=state.branch;render()};bindGlobal()}
function pageHead(eyebrow,title,subtitle,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="button-row">${buttons}</div></div>`}
function foot(){return '<div class="footer-line"><span>Sunrise Family Clinics · CareBridge CMS</span><span>Interactive prototype · Fictional data · 19 October 2026</span></div>'}
function stat(label,value,foot,icon){return `<div class="stat"><div class="stat-top">${label}${ic(icon)}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function appointmentRows(appointments){return appointments.map(a=>`<tr><td class="time">${esc(a.time)}</td><td>${person(patient(a.patient))}</td><td>${esc(a.service)}</td><td>${badge(a.status)}</td><td><button class="icon-btn" data-appointment="${a.id}" aria-label="View appointment for ${esc(patient(a.patient).name)}">${ic('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No appointments for this branch today.</td></tr>'}
function renderOverview(){const appts=db.appointments.filter(a=>a.date===TODAY&&a.branch===state.branch).sort((a,b)=>a.time.localeCompare(b.time));const inv=db.invoices.filter(i=>i.branch===state.branch&&i.date===TODAY),paid=inv.filter(i=>i.status==='Paid').reduce((s,i)=>s+total(i),0);const bi=branches.indexOf(state.branch);const low=db.stock.filter(m=>m.qty[bi]<m.min);const exp=db.stock.filter(m=>m.expiry<='2026-11-18');const can=k=>permissions[state.role].includes(k);$('#content').innerHTML=pageHead('YOUR CLINIC AT A GLANCE','Good morning, '+roleNames[state.role].replace('Dr. ','').split(' ')[0]+'.','Here’s what’s happening at '+esc(state.branch)+' today.',can('appointments')?`<button class="btn primary" data-action="book">${ic('plus')}New appointment</button>`:'')+`<div class="stat-grid">${stat('Today’s appointments',appts.length,'<span class="dot"></span> Monday, 19 October','calendar')}${stat('Patients checked in',appts.filter(a=>a.status==='Checked in'||a.status==='In consultation').length,'From today’s appointments','users')}${stat('Payments received',money(paid),'Recorded at this branch today','receipt')}${stat('Stock alerts',low.length+exp.length,low.length+' low stock · '+exp.length+' expiring','pill')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Today’s appointments</h2><p>Keep the day moving, one patient at a time.</p></div>${can('appointments')?'<button class="text-btn" data-nav="appointments">View schedule →</button>':''}</div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Patient</th><th>Service</th><th>Status</th><th></th></tr></thead><tbody>${appointmentRows(appts.slice(0,5))}</tbody></table></div><div class="panel-footer"><span>${appts.length} appointments · ${esc(state.branch)}</span><span>19 Oct 2026</span></div></section><section class="panel"><div class="panel-head"><div><h2>Needs attention</h2><p>A little visibility goes a long way.</p></div><span class="tag red">${low.length+exp.length} alerts</span></div>${low.slice(0,2).map(m=>`<div class="alert-row"><div class="alert-icon">${ic('pill')}</div><div><h3>${esc(m.name)}</h3><p>${m.qty[bi]} units left · Below ${m.min}-unit threshold</p>${can('pharmacy')?`<button class="text-btn" data-stock="${m.id}">Request stock transfer →</button>`:''}</div></div>`).join('')}${exp.slice(0,1).map(m=>`<div class="alert-row"><div class="alert-icon">${ic('clock')}</div><div><h3>Batch approaching expiry</h3><p>${esc(m.name)} · Batch ${m.batch}<br>Expires ${dateLabel(m.expiry)}</p>${can('pharmacy')?'<button class="text-btn" data-nav="pharmacy">Review inventory →</button>':''}</div></div>`).join('')}${!low.length&&!exp.length?'<div class="empty">No stock alerts at this branch.</div>':''}<div class="alert-row"><div class="alert-icon" style="background:#f2f3f5;color:#747a86">${ic('branch')}</div><div><h3>Five branches. One patient record.</h3><p>Authorised clinical staff can view visit history across the SFC network.</p></div></div></section></div><section class="panel section-gap"><div class="panel-head"><div><h2>Across the network</h2><p>Today’s scheduled appointments by branch.</p></div><span class="tag green"><span class="dot" style="background:var(--green)"></span> 5 branches connected</span></div><div class="network">${branches.map(b=>`<div class="network-item"><small>${b}</small><strong>${db.appointments.filter(a=>a.branch===b&&a.date===TODAY).length}</strong><span>appointments today</span></div>`).join('')}</div></section>`+foot()}
function renderPatients(){if(state.patientView){renderPatientProfile();return}$('#content').innerHTML=pageHead('ONE CONNECTED RECORD','Patients','Find and manage patient registration across all five branches.',state.role!=='Doctor'?`<button class="btn primary" data-action="register">${ic('plus')}Register patient</button>`:'')+`<section class="panel"><div class="filter-bar"><label class="sr-only" for="patient-search">Search patients</label><input class="search" id="patient-search" placeholder="Search name, patient ID or phone"><span class="muted small">All branches · ${db.patients.length} patients</span></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Contact</th><th>Registered branch</th><th>Last visit</th><th></th></tr></thead><tbody id="patient-rows"></tbody></table></div><div class="panel-footer">Shared registration helps prevent duplicate records between branches.</div></section>`+foot();function rows(q=''){$('#patient-rows').innerHTML=db.patients.filter(p=>(p.name+' '+p.id+' '+p.phone).toLowerCase().includes(q.toLowerCase())).map(p=>`<tr><td>${person(p)}</td><td>${esc(p.phone)}<br><small>${esc(p.email)}</small></td><td>${esc(p.branch)}</td><td>${p.visits.length?dateLabel(p.visits[0].date):'<span class="muted">No visits yet</span>'}</td><td><button class="btn small" data-patient="${p.id}">Open record ${ic('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching patients. Try a different name, ID or phone.</td></tr>';bindGlobal()}rows();$('#patient-search').oninput=e=>rows(e.target.value)}
function renderPatientProfile(){const p=patient(state.patient);const clinical=['Manager','Doctor'].includes(state.role);$('#content').innerHTML=pageHead('PATIENT RECORD',esc(p.name),`${esc(p.id)} · Shared across the SFC network`,`<button class="btn" data-action="patients-back">Back to patients</button>${clinical?`<button class="btn primary" data-action="consult">${ic('plus')}New consultation</button>`:`<button class="btn primary" data-book-patient="${p.id}">${ic('calendar')}Book appointment</button>`}`)+`<div class="two-col"><div class="stack"><section class="panel"><div class="profile-head"><span class="avatar">${initials(p.name)}</span><div><h2>${esc(p.name)}</h2><div class="profile-meta"><span>${p.gender}</span><span>Born ${dateLabel(p.dob)}</span><span>${p.id}</span></div></div></div><div class="panel-body" style="border-top:1px solid var(--line)"><div class="detail-grid"><div class="detail"><small>Mobile number</small><strong>${esc(p.phone)}</strong></div><div class="detail"><small>Email address</small><strong>${esc(p.email)}</strong></div><div class="detail"><small>Registered at</small><strong>${esc(p.branch)}</strong></div><div class="detail"><small>Record availability</small><strong>All five SFC branches</strong></div></div></div></section><section class="panel"><div class="panel-head"><div><h2>Medical history</h2><p>Visits and tests from every SFC branch.</p></div><span class="tag">${p.visits.length} visits</span></div>${clinical?`<div class="timeline">${p.visits.map(v=>`<article class="visit"><div class="visit-title"><h3>${esc(v.reason)}</h3><span class="tag">${dateLabel(v.date)}</span></div><small>${esc(v.doctor)} · ${esc(v.branch)}</small><p>${esc(v.notes)}</p>${v.tests?`<p><strong>Tests:</strong> ${esc(v.tests)}</p>`:''}</article>`).join('')||'<div class="empty">No consultation records yet.</div>'}</div>`:`<div class="panel-body"><div class="notice">${ic('lock')} Clinical notes are available to doctors and authorised managers. Reception staff can manage registration and appointments.</div></div>`}</section></div><aside class="stack">${clinical?`<section class="panel"><div class="panel-head"><h2>Clinical alerts</h2>${ic('heart')}</div><div class="panel-body"><small class="muted">Recorded allergies</small><p style="margin-top:8px">${p.allergy==='None recorded'?badge('None recorded'):`<span class="tag red">${esc(p.allergy)}</span>`}</p><p class="info-note">Review the patient’s recorded history before completing a consultation.</p></div></section>`:''}<section class="panel"><div class="panel-head"><h2>Upcoming appointments</h2></div><div class="panel-body">${db.appointments.filter(a=>a.patient===p.id&&a.date>=TODAY&&a.status!=='Completed').map(a=>`<div style="padding-bottom:15px"><strong class="small">${dateLabel(a.date)} · ${a.time}</strong><p class="info-note" style="margin-top:3px">${a.branch}<br>${a.doctor}</p></div>`).join('')||'<p class="muted small">No upcoming appointments.</p>'}</div></section></aside></div>`+foot()}
function registerModal(){openModal('Register patient','Create a shared patient record for all five branches.',`<form id="register-form"><div class="form-grid">${field('Full name','name','text','',true)}${field('Date of birth','dob','date','',true)}${selectField('Gender','gender',['Female','Male','Prefer not to say'])}${field('Mobile number','phone','tel','',true)}${field('Email address','email','email','',true)}${selectField('Registered branch','branch',branches,state.branch)}</div><p class="info-note">Search existing records before registering a patient. Required fields are marked with *.</p><p id="register-error" class="form-error" role="alert"></p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="register-form">Create patient record</button>`);$('#register-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.dob>TODAY){$('#register-error').textContent='Date of birth cannot be in the future.';return}if(!/^[+\d\s-]{9,16}$/.test(f.phone)){$('#register-error').textContent='Enter a valid phone number with 9–16 characters.';return}if(db.patients.some(p=>p.name.toLowerCase().trim()===f.name.toLowerCase().trim()&&p.dob===f.dob)){$('#register-error').textContent='A patient with this name and date of birth already exists. Open the existing record.';return}const p={...f,name:f.name.trim(),id:nextId('SFC-',db.patients),allergy:'None recorded',visits:[]};db.patients.push(p);persist();state.patient=p.id;state.patientView=true;state.page='patients';closeModal();render();toast('Patient registered. The record is available across all branches.')}}
function consultModal(){const p=patient(state.patient);openModal('New consultation',p.name+' · '+p.id,`<form id="consult-form"><div class="notice">Recorded allergies: ${esc(p.allergy)}</div><div class="form-grid" style="margin-top:18px">${field('Visit date','date','date',TODAY,true)}${selectField('Consulting doctor','doctor',doctors,state.role==='Doctor'?doctors[0]:state.doctor)}${field('Reason for visit','reason','text','',true,'full')}<label class="field full">Consultation notes <span class="required">*</span><textarea name="notes" required placeholder="Enter the consultation summary"></textarea></label><label class="field full">Tests or results<textarea name="tests" placeholder="Record relevant tests or results, if any"></textarea></label></div><p id="consult-error" class="form-error" role="alert"></p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" form="consult-form">Save consultation</button>`);$('#consult-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.date>TODAY){$('#consult-error').textContent='Consultation date cannot be later than the prototype date.';return}p.visits.unshift({...f,branch:state.branch});persist();closeModal();render();toast('Consultation saved to the shared patient record.')}}
function renderAppointments(){const list=db.appointments.filter(a=>a.date===state.date&&a.branch===state.branch&&a.doctor===state.doctor).sort((a,b)=>a.time.localeCompare(b.time));$('#content').innerHTML=pageHead('PLAN A SMOOTHER DAY','Appointments','Manage available slots, bookings and patient arrivals.',`<button class="btn" data-action="portal">Patient portal ${ic('arrow')}</button><button class="btn primary" data-action="book">${ic('plus')}New appointment</button>`)+`<div class="calendar-layout"><section class="panel"><div class="panel-head"><div><h2>${dateLabel(state.date)}</h2><p>${esc(state.branch)} · ${list.length} scheduled appointments</p></div><select class="select" id="schedule-doctor" aria-label="Filter by doctor">${option(doctors,state.doctor)}</select></div><div class="schedule">${slots.map(t=>{const a=list.find(a=>a.time===t);return `<div class="schedule-row"><span class="schedule-time">${t}</span>${a?`<div class="appointment"><div><strong>${esc(patient(a.patient).name)}</strong><small>${esc(a.service)} · ${esc(a.source)}</small></div><div class="button-row">${badge(a.status)}<button class="icon-btn" data-appointment="${a.id}" aria-label="View ${esc(patient(a.patient).name)} appointment">${ic('chevron')}</button></div></div>`:`<div class="empty-slot">Available slot <button data-book-time="${t}">+ Book</button></div>`}</div>`}).join('')}</div></section><aside class="stack"><section class="panel"><div class="panel-head"><h2>Choose a date</h2>${ic('calendar')}</div><div class="panel-body"><label class="field">Appointment date<input id="schedule-date" type="date" value="${state.date}" min="${TODAY}"></label><div class="calendar-mini"><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span>${'<span></span><span></span><span></span>'}${Array.from({length:31},(_,i)=>`<button data-day="2026-10-${String(i+1).padStart(2,'0')}" ${i+1<19?'disabled':''} class="${state.date===`2026-10-${String(i+1).padStart(2,'0')}`?'active':''}">${i+1}</button>`).join('')}</div><p class="info-note">October 2026 · Booking starts from 19 October in this prototype.</p></div></section><section class="panel"><div class="panel-head"><h2>Booking safeguards</h2></div><div class="panel-body"><div class="notice">A doctor’s occupied time slots are blocked across branches to help prevent double booking.</div><p class="info-note">Confirmations and reminder messages can be previewed from each appointment.</p></div></section></aside></div>`+foot();$('#schedule-date').onchange=e=>{if(e.target.value>=TODAY){state.date=e.target.value;render()}else toast('Choose 19 October 2026 or a later date.')};$('#schedule-doctor').onchange=e=>{state.doctor=e.target.value;render()}}
let booking={};
function bookingFields(portal=false){return `<div class="form-grid">${portal?'':`<label class="field full">Patient <span class="required">*</span><select name="patient" required>${db.patients.map(p=>`<option value="${p.id}" ${p.id===booking.patient?'selected':''}>${esc(p.name)} · ${p.id}</option>`).join('')}</select></label>`}${selectField('Clinic branch','branch',branches,booking.branch)}${selectField('Service','service',['General practice','Paediatric','Dental'],booking.service)}${field('Appointment date','date','date',booking.date,true)}${selectField('Doctor','doctor',doctors,booking.doctor)}</div><div class="slots-title">Available time slots <span class="required">*</span></div><div class="slots" id="booking-slots"></div><div class="slot-legend"><span>All times MYT</span><span>Crossed-out slots are already booked</span></div><input type="hidden" name="time" id="booking-time" value=""><p class="form-error" id="booking-error" role="alert"></p>`}
function bookModal(patientId,time){booking={patient:patientId||state.patient||db.patients[0].id,branch:state.branch,doctor:state.doctor,date:state.date,time:time||'',service:'General practice'};openModal('New appointment','Select a patient, branch and available time.',`<form id="booking-form">${bookingFields()}<p class="info-note">The selected slot is checked again when you confirm the booking.</p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" form="booking-form">Confirm appointment</button>`);bindBooking($('#booking-form'));$('#booking-form').onsubmit=e=>{e.preventDefault();submitBooking(e.target,false)}}
function occupied(date,doctor,time){return db.appointments.some(a=>a.date===date&&a.doctor===doctor&&a.time===time&&a.status!=='Cancelled')}
function bindBooking(form){form.elements.date.min=TODAY;for(const k of ['branch','doctor','date','service'])form.elements[k].onchange=()=>{booking[k]=form.elements[k].value;if(k!=='service')booking.time='';renderSlots(form)};renderSlots(form)}
function renderSlots(form){const date=form.elements.date.value,doc=form.elements.doctor.value;$('#booking-slots').innerHTML=slots.map(t=>`<button type="button" class="slot ${booking.time===t?'active':''}" data-slot="${t}" ${occupied(date,doc,t)?'disabled aria-label="'+t+' already booked"':''}>${t}</button>`).join('');$('#booking-time').value=booking.time&&!occupied(date,doc,booking.time)?booking.time:'';$$('[data-slot]').forEach(b=>b.onclick=()=>{booking.time=b.dataset.slot;$('#booking-error').textContent='';renderSlots(form)})}
function submitBooking(form,portal){const f=Object.fromEntries(new FormData(form));const err=$('#booking-error');if(f.date<TODAY){err.textContent='Choose 19 October 2026 or a later date.';return}if(!f.time){err.textContent='Select an available time slot.';return}if(occupied(f.date,f.doctor,f.time)){err.textContent='That time has just been booked. Please choose another slot.';booking.time='';renderSlots(form);return}let pid=f.patient;if(portal){if(!/^[+\d\s-]{9,16}$/.test(f.phone)){err.textContent='Enter a valid mobile number with 9–16 characters.';return}const match=db.patients.find(p=>p.phone.replace(/\D/g,'')===f.phone.replace(/\D/g,'')&&p.name.trim().toLowerCase()===f.name.trim().toLowerCase());if(match)pid=match.id;else{const p={id:nextId('SFC-',db.patients),name:f.name.trim(),phone:f.phone,email:f.email,dob:'',gender:'Not specified',branch:f.branch,allergy:'None recorded',visits:[]};db.patients.push(p);pid=p.id}}if(db.appointments.some(a=>a.patient===pid&&a.date===f.date&&a.time===f.time&&a.status!=='Cancelled')){err.textContent='This patient already has an appointment at that time.';return}const a={id:nextId('APT-',db.appointments),patient:pid,date:f.date,time:f.time,branch:f.branch,doctor:f.doctor,service:f.service,status:'Confirmed',source:portal?'Online':'Front desk'};db.appointments.push(a);persist();if(portal){renderPortalSuccess(a)}else{closeModal();state.date=f.date;state.doctor=f.doctor;state.branch=f.branch;state.page='appointments';render();appointmentConfirmation(a)}}
function appointmentConfirmation(a){openModal('Appointment confirmed','The booking is now visible in the staff schedule.',`<div class="success"><div class="success-mark">${ic('check')}</div><h2>You’re all set.</h2><p>${esc(patient(a.patient).name)} has a confirmed appointment.</p>${appointmentSummary(a)}</div>`,`<button class="btn" data-reminder="${a.id}">Preview reminder</button><button class="btn primary" data-action="close">Done</button>`)}
function appointmentSummary(a){return `<div class="summary-list"><div><span>Booking reference</span><strong>${a.id}</strong></div><div><span>Date and time</span><strong>${dateLabel(a.date)} · ${a.time} MYT</strong></div><div><span>Clinic</span><strong>${a.branch}</strong></div><div><span>Doctor</span><strong>${a.doctor}</strong></div><div><span>Service</span><strong>${a.service}</strong></div></div>`}
function appointmentDetails(id){const a=db.appointments.find(a=>a.id===id);openModal('Appointment details',patient(a.patient).name+' · '+a.id,appointmentSummary(a)+`<div style="margin-top:20px">${badge(a.status)}</div><p class="info-note">Booked through ${a.source.toLowerCase()}.</p>`,`<button class="btn" data-reminder="${a.id}">Preview reminder</button>${a.status==='Confirmed'?`<button class="btn primary" data-checkin="${a.id}">Check in patient</button>`:''}<button class="btn" data-action="close">Close</button>`)}
function reminder(id){const a=db.appointments.find(a=>a.id===id);openModal('Appointment reminder','Message preview for '+patient(a.patient).phone,`<div class="reminder"><div class="eyebrow">SFC REMINDERS</div><div class="bubble">Hello ${esc(patient(a.patient).name)}, your ${esc(a.service.toLowerCase())} appointment at Sunrise Family Clinics, ${a.branch}, is confirmed for <strong>${dateLabel(a.date)} at ${a.time} MYT</strong> with ${a.doctor}.<br><br>Booking reference: ${a.id}. Please arrive 10 minutes early.</div></div><p class="info-note">This prototype previews the reminder. No SMS or email is sent.</p>`,`<button class="btn primary" data-action="close">Done</button>`)}
function stockStatus(m,bi){return m.qty[bi]<m.min?'Low stock':m.expiry<='2026-11-18'?'Expiring soon':'Available'}
function renderPharmacy(){const bi=branches.indexOf(state.inventoryBranch);$('#content').innerHTML=pageHead('STOCK VISIBILITY ACROSS BRANCHES','Pharmacy','Monitor medicine levels, expiry dates and stock transfers.',`<button class="btn primary" data-action="transfer">${ic('plus')}Request transfer</button>`)+`<div class="stat-grid">${stat('Medicine lines',db.stock.length,'Sample stock catalogue','pill')}${stat('Low-stock lines',db.stock.filter(m=>m.qty[bi]<m.min).length,state.inventoryBranch,'alert')}${stat('Expiring in 30 days',db.stock.filter(m=>m.expiry>='2026-10-19'&&m.expiry<='2026-11-18').length,'Review batches before dispensing','clock')}${stat('Pending transfers',db.transfers.filter(t=>t.status==='Pending receipt').length,'Across the SFC network','branch')}</div><div class="tabs"><button class="tab ${state.stockTab==='stock'?'active':''}" data-stock-tab="stock">Medicine inventory</button><button class="tab ${state.stockTab==='transfers'?'active':''}" data-stock-tab="transfers">Transfer requests (${db.transfers.length})</button></div><section class="panel">${state.stockTab==='stock'?`<div class="filter-bar"><input id="medicine-search" class="search" placeholder="Search medicine or batch" aria-label="Search medicine or batch"><select class="select" id="inventory-branch" aria-label="Inventory branch">${option(branches,state.inventoryBranch)}</select><span class="small muted">Units per listed batch</span></div><div class="table-wrap"><table><thead><tr><th>Medicine</th><th>In stock</th><th>Minimum</th><th>Expiry date</th><th>Status</th><th></th></tr></thead><tbody id="stock-rows"></tbody></table></div>`:`<div class="panel-head"><div><h2>Inter-branch transfers</h2><p>Requested stock is reserved at the source until receipt.</p></div></div><div class="table-wrap"><table><thead><tr><th>Reference / Medicine</th><th>From → To</th><th>Quantity</th><th>Status</th><th></th></tr></thead><tbody>${db.transfers.map(t=>`<tr><td><strong>${esc(db.stock.find(m=>m.id===t.medicine).name)}</strong><br><small>${t.id}</small></td><td>${t.from}<br><small>→ ${t.to}</small></td><td>${t.qty} units</td><td>${badge(t.status)}</td><td>${t.status==='Pending receipt'?`<button class="btn small" data-receive="${t.id}">Confirm receipt</button>`:'<span class="small green">Stock updated</span>'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No transfer requests yet. Create a request from a medicine stock alert.</td></tr>'}</tbody></table></div>`}<div class="panel-footer">Low stock means available quantity is below the minimum threshold.</div></section>`+foot();if(state.stockTab==='stock'){function rows(q=''){$('#stock-rows').innerHTML=db.stock.filter(m=>(m.name+' '+m.batch).toLowerCase().includes(q.toLowerCase())).map(m=>`<tr><td><strong>${m.name}</strong><br><small>${m.category} · ${m.batch}</small></td><td><span class="stock-value ${m.qty[bi]<m.min?'low':''}">${m.qty[bi]}</span> <small>units</small></td><td>${m.min}</td><td>${dateLabel(m.expiry)}</td><td>${badge(stockStatus(m,bi))}</td><td><button class="btn small" data-stock="${m.id}">Transfer ${ic('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching medicine or batch.</td></tr>';bindGlobal()}rows();$('#medicine-search').oninput=e=>rows(e.target.value);$('#inventory-branch').onchange=e=>{state.inventoryBranch=e.target.value;render()}}}
function transferModal(id){const medicine=db.stock.find(m=>m.id===id)||db.stock[0];const dest=state.inventoryBranch;const source=branches.find((b,i)=>b!==dest&&medicine.qty[i]>medicine.min)||branches.find(b=>b!==dest);openModal('Request stock transfer','Move available stock between SFC branches.',`<form id="transfer-form"><div class="form-grid">${selectField('Medicine / batch','medicine',db.stock.map(m=>m.id+' | '+m.name),medicine.id+' | '+medicine.name,'full')}${selectField('Source branch','from',branches,source)}${selectField('Destination branch','to',branches,dest)}${field('Quantity in units','qty','number','50',true)}<div class="field"><span>Source availability</span><strong id="transfer-availability" style="padding-top:9px"></strong></div></div><p class="info-note">The source quantity is reserved when requested. The destination quantity increases after receipt is confirmed.</p><p id="transfer-error" class="form-error" role="alert"></p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" form="transfer-form">Request transfer</button>`);const f=$('#transfer-form');f.elements.qty.min=1;f.elements.qty.step=1;const update=()=>{const m=db.stock.find(m=>m.id===f.elements.medicine.value.split(' | ')[0]);$('#transfer-availability').textContent=m.qty[branches.indexOf(f.elements.from.value)]+' units'};f.elements.from.onchange=update;f.elements.medicine.onchange=update;update();f.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f)),m=db.stock.find(m=>m.id===data.medicine.split(' | ')[0]),qty=Number(data.qty);if(data.from===data.to){$('#transfer-error').textContent='Choose different source and destination branches.';return}if(!Number.isInteger(qty)||qty<1||qty>m.qty[branches.indexOf(data.from)]){$('#transfer-error').textContent='Enter a whole-number quantity within the available source stock.';return}m.qty[branches.indexOf(data.from)]-=qty;db.transfers.unshift({id:nextId('TRF-',db.transfers),medicine:m.id,from:data.from,to:data.to,qty,status:'Pending receipt'});persist();closeModal();state.page='pharmacy';state.stockTab='transfers';render();toast('Transfer requested. Source stock reserved; awaiting receipt.')}}
function renderBilling(){const invs=db.invoices.filter(i=>i.branch===state.branch);$('#content').innerHTML=pageHead('A CLEARER CHECKOUT','Billing & claims','Generate invoices, record payments and track panel claims.',`<button class="btn primary" data-action="invoice-new">${ic('plus')}New invoice</button>`)+`<div class="stat-grid">${stat('Branch invoices',invs.length,'All sample dates','receipt')}${stat('Payments received',money(invs.filter(i=>i.status==='Paid').reduce((s,i)=>s+total(i),0)),'Recorded payments only','check')}${stat('Unpaid invoices',invs.filter(i=>i.status==='Unpaid').length,'Awaiting payment or panel claim','clock')}${stat('Active claims',db.claims.filter(c=>db.invoices.some(i=>i.id===c.invoice&&i.branch===state.branch)).length,'Claims for this branch','branch')}</div><div class="tabs"><button class="tab ${state.billingTab==='invoices'?'active':''}" data-billing-tab="invoices">Invoices</button><button class="tab ${state.billingTab==='claims'?'active':''}" data-billing-tab="claims">Insurance & panel claims</button></div><section class="panel"><div class="panel-head"><div><h2>${state.billingTab==='invoices'?'Patient invoices':'Claim tracking'}</h2><p>${state.branch} · Amounts in Malaysian Ringgit</p></div></div><div class="table-wrap"><table>${state.billingTab==='invoices'?`<thead><tr><th>Invoice</th><th>Patient</th><th>Date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${invs.map(i=>`<tr><td><strong>${i.id}</strong></td><td>${person(patient(i.patient))}</td><td>${dateLabel(i.date)}</td><td>${money(total(i))}</td><td>${badge(i.status)}</td><td><button class="btn small" data-invoice="${i.id}">View invoice ${ic('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No invoices at this branch. Create an invoice to start.</td></tr>'}</tbody>`:`<thead><tr><th>Claim / Invoice</th><th>Patient</th><th>Panel / insurer</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${db.claims.filter(c=>invs.some(i=>i.id===c.invoice)).map(c=>{const i=invs.find(i=>i.id===c.invoice);return `<tr><td><strong>${c.id}</strong><br><small>${c.invoice}</small></td><td>${person(patient(i.patient))}</td><td>${esc(c.provider)}</td><td>${money(total(i))}</td><td>${badge(c.status)}</td><td><button class="btn small" data-claim="${c.id}">View claim</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No panel claims for this branch. Open an unpaid invoice to prepare a claim.</td></tr>'}</tbody>`}</table></div></section>`+foot()}
function newInvoice(){openModal('Generate invoice','Create itemised charges for a recorded patient visit.',`<form id="invoice-form"><div class="form-grid"><label class="field full">Patient <span class="required">*</span><select name="patient">${db.patients.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.id}</option>`).join('')}</select></label>${field('Consultation charge (RM)','consultation','number','45.00',true)}${field('Dispensed items (RM)','medicine','number','0.00',true)}</div><p class="info-note" id="visit-charge-note">Charges use sample rates. Select a patient to view their latest recorded visit.</p><p class="form-error" id="invoice-error" role="alert"></p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" form="invoice-form">Generate invoice</button>`);const form=$('#invoice-form');for(const k of ['consultation','medicine']){form.elements[k].min=0;form.elements[k].step='.01'}const update=()=>{const p=patient(form.elements.patient.value);$('#visit-charge-note').textContent=p.visits.length?'Latest visit: '+p.visits[0].reason+' · '+dateLabel(p.visits[0].date)+'. Review charges before generating.':'No consultation recorded yet. Record a consultation before generating an invoice.'};form.elements.patient.onchange=update;update();form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));const p=patient(f.patient);if(!p.visits.length){$('#invoice-error').textContent='This patient has no recorded visit. A doctor or manager must save a consultation first.';return}const x=Number(f.consultation),y=Number(f.medicine);if(!Number.isFinite(x+y)||x<0||y<0||x+y<=0){$('#invoice-error').textContent='Enter non-negative charges with a total above RM 0.00.';return}const i={id:nextId('INV-',db.invoices),patient:f.patient,branch:state.branch,date:TODAY,items:[{name:'Consultation',qty:1,price:x},...(y>0?[{name:'Dispensed items',qty:1,price:y}]:[])],status:'Unpaid',method:''};db.invoices.unshift(i);persist();closeModal();render();invoiceModal(i.id)}}
function invoiceModal(id){const i=db.invoices.find(i=>i.id===id),p=patient(i.patient);openModal('Invoice '+i.id,'Review charges and choose payment or panel billing.',`<div class="invoice-paper" id="invoice-print"><div class="invoice-top"><div class="invoice-brand"><img src="assets/logo.svg" alt=""><div><strong>Sunrise Family Clinics</strong><small>${i.branch}</small></div></div><div style="text-align:right"><strong>${i.id}</strong><br><small>${dateLabel(i.date)}</small></div></div><div class="detail-grid" style="margin-bottom:22px"><div class="detail"><small>Billed to</small><strong>${esc(p.name)}</strong><br><small>${p.id}</small></div><div class="detail" style="text-align:right"><small>Payment status</small>${badge(i.status)}</div></div><table><thead><tr><th>Description</th><th>Qty</th><th style="text-align:right">Amount</th></tr></thead><tbody>${i.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.qty}</td><td style="text-align:right">${money(x.price*x.qty)}</td></tr>`).join('')}</tbody></table><div class="invoice-total"><small>Total due</small>${money(total(i))}</div>${i.status==='Paid'?`<p class="info-note" style="text-align:right">Payment recorded by ${esc(i.method)}.</p>`:''}</div><p class="info-note">Sample invoice for the interface prototype.</p>`,`<button class="btn" data-action="print">${ic('print')}Print / save PDF</button>${i.status==='Unpaid'?`<button class="btn" data-claim-invoice="${i.id}">Prepare panel claim</button><button class="btn primary" data-pay="${i.id}">Record payment</button>`:'<button class="btn primary" data-action="close">Done</button>'}`,true)}
function paymentModal(id){const i=db.invoices.find(i=>i.id===id);openModal('Record payment',i.id+' · '+money(total(i)),`<form id="payment-form"><div class="form-grid">${selectField('Payment method','method',['Card','Cash','Online transfer'],'Card','full')}</div><div class="booking-summary"><span>Amount to record</span><strong>${money(total(i))}</strong></div><p class="info-note">This records a simulated payment. No bank or payment service is contacted.</p></form>`,`<button class="btn" data-invoice="${i.id}">Back</button><button class="btn primary" form="payment-form">Confirm payment</button>`);$('#payment-form').onsubmit=e=>{e.preventDefault();i.status='Paid';i.method=e.target.elements.method.value;persist();closeModal();render();invoiceModal(id);toast('Payment recorded. Invoice marked as paid.')}}
function claimForm(id){const i=db.invoices.find(i=>i.id===id),p=patient(i.patient);if(db.claims.some(c=>c.invoice===id)){toast('A claim already exists for this invoice.');return}openModal('Prepare panel claim',i.id+' · '+p.name,`<form id="claim-form" novalidate><div class="booking-summary" style="margin-top:0;margin-bottom:20px"><span>Claim amount from invoice</span><strong>${money(total(i))}</strong></div><div class="form-grid">${selectField('Panel / insurance provider','provider',['','CarePlus Panel','FamilyCare Insurance','Corporate Health Panel'])}${field('Member / policy number','member','text','',true)}<label class="field full">Service and diagnosis reference <span class="required">*</span><textarea name="diagnosis" placeholder="Enter the reference provided by the clinic"></textarea></label></div><label class="check-row"><input name="reviewed" type="checkbox">I have reviewed the patient details, invoice and supporting documentation.</label><p class="form-error" id="claim-error" role="alert"></p><p class="info-note">Submission is simulated. No patient information is sent to an insurer.</p></form>`,`<button class="btn" data-invoice="${id}">Back</button><button class="btn primary" form="claim-form">Validate and submit</button>`);$('#claim-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const missing=[];if(!f.provider)missing.push('provider');if(!f.member.trim())missing.push('member / policy number');if(!f.diagnosis.trim())missing.push('service reference');if(!f.reviewed)missing.push('review confirmation');if(missing.length){$('#claim-error').textContent='Complete before submission: '+missing.join(', ')+'.';return}const c={id:nextId('CLM-',db.claims),invoice:id,provider:f.provider,member:f.member.trim(),diagnosis:f.diagnosis.trim(),status:'Submitted',date:TODAY};db.claims.unshift(c);i.status='Panel';i.method='Panel / insurance';persist();state.billingTab='claims';closeModal();render();claimDetails(c.id);toast('Claim validated and added to the tracking list.')}}
function claimDetails(id){const c=db.claims.find(c=>c.id===id),i=db.invoices.find(i=>i.id===c.invoice);openModal('Claim '+c.id,'Insurance and panel claim tracking',`<div class="summary-list" style="margin:0"><div><span>Patient</span><strong>${esc(patient(i.patient).name)}</strong></div><div><span>Invoice</span><strong>${i.id}</strong></div><div><span>Provider</span><strong>${esc(c.provider)}</strong></div><div><span>Member reference</span><strong>${esc(c.member)}</strong></div><div><span>Amount</span><strong>${money(total(i))}</strong></div><div><span>Submitted</span><strong>${dateLabel(c.date)}</strong></div><div><span>Status</span>${badge(c.status)}</div></div><p class="info-note">Service reference: ${esc(c.diagnosis)}<br>The prototype records submission status locally. Provider responses are not connected.</p>`,`<button class="btn primary" data-action="close">Done</button>`)}
const reportData={'2026-10':[24680,18950,21800,17520,23140],'2026-09':[22550,17400,20100,16800,21450],'2026-08':[20100,16800,19400,15900,20300]};
function reportStats(){const rows=reportData[state.month];return {rows,sum:rows.reduce((a,b)=>a+b,0),claims:state.month==='2026-10'?48:state.month==='2026-09'?43:40,visits:state.month==='2026-10'?9840:state.month==='2026-09'?9250:8910}}
function renderReports(){const r=reportStats();$('#content').innerHTML=pageHead('THE BIGGER PICTURE','Management reports','A consolidated view of revenue, claims and stock across all five branches.',`<button class="btn" data-action="report-print">${ic('print')}Print report</button><button class="btn primary" data-action="report-export">${ic('download')}Export CSV</button>`)+`<div class="filter-bar" style="background:white;border:1px solid var(--line);border-radius:8px;margin-bottom:22px"><label for="report-month" class="small muted">Reporting period</label><select id="report-month" class="select">${[['2026-10','October 2026'],['2026-09','September 2026'],['2026-08','August 2026']].map(([v,l])=>`<option value="${v}" ${v===state.month?'selected':''}>${l}</option>`).join('')}</select><span class="small muted">All branches · Illustrative monthly dataset</span></div><div class="print-title"><h1>SFC Management Report</h1><p>${state.month} · All five branches · Illustrative data</p></div><div class="stat-grid">${stat('Total revenue',money(r.sum),'Consolidated monthly sample','receipt')}${stat('Patient visits',r.visits.toLocaleString(),'Across all five branches','users')}${stat('Submitted claims',r.claims,'Illustrative monthly count','branch')}${stat('Low-stock lines',db.stock.reduce((s,m)=>s+m.qty.filter(q=>q<m.min).length,0),'Current prototype inventory','pill')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Revenue by branch</h2><p>${state.month} · Consolidated sample amounts</p></div><span class="tag">MYR</span></div><div class="panel-body">${branches.map((b,i)=>`<div class="report-bar"><span>${b}</span><div class="bar"><span style="width:${r.rows[i]/Math.max(...r.rows)*100}%"></span></div><strong>${money(r.rows[i])}</strong></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Revenue trend</h2><p>August to October 2026</p></div></div><div class="panel-body"><div class="chart">${Object.entries(reportData).reverse().map(([m,values])=>{const sum=values.reduce((a,b)=>a+b,0);return `<div class="chart-col"><span>${money(sum)}</span><div class="col" style="height:${sum/110000*125}px"></div><small>${m==='2026-08'?'AUG':m==='2026-09'?'SEP':'OCT'}</small></div>`}).join('')}</div><div class="report-legend"><span>Monthly total</span><span>All branches</span></div></div></section></div><section class="panel section-gap"><div class="panel-head"><div><h2>Network stock overview</h2><p>Current sample stock · Units by branch</p></div></div><div class="table-wrap"><table><thead><tr><th>Medicine</th>${branches.map(b=>`<th>${b}</th>`).join('')}</tr></thead><tbody>${db.stock.map(m=>`<tr><td>${m.name}</td>${m.qty.map(q=>`<td><span class="${q<m.min?'stock-value low':''}">${q}</span>${q<m.min?' <span class="tag red">Low</span>':''}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><p class="info-note">Monthly revenue, visit and claim figures are illustrative reporting data. Current inventory reflects changes made in this browser.</p>`+foot();$('#report-month').onchange=e=>{state.month=e.target.value;render()}}
function exportReport(){const r=reportStats();let rows=[['SFC Management Report',state.month],['Dataset','Illustrative monthly sample'],[],['Branch','Revenue (RM)'],...branches.map((b,i)=>[b,r.rows[i].toFixed(2)]),['Total',r.sum.toFixed(2)],[],['Medicine',...branches],...db.stock.map(m=>[m.name,...m.qty])];download(rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'SFC-report-'+state.month+'.csv','text/csv');toast('Monthly report exported as CSV.')}
function download(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function field(label,name,type,value='',required=false,cls=''){return `<label class="field ${cls}">${label}${required?' <span class="required">*</span>':''}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`}
function selectField(label,name,values,selected,cls=''){return `<label class="field ${cls}">${label}<select name="${name}">${option(values,selected)}</select></label>`}
let returnFocus;
function openModal(title,sub,body,footer,wide=false){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${sub}</p></div><button class="icon-btn" data-action="close" aria-label="Close dialog">${ic('close')}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${footer}</div></section></div>`;document.body.style.overflow='hidden';bindGlobal();setTimeout(()=>$('.modal input:not([type=hidden]),.modal select,.modal button')?.focus(),30);$('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()}}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';returnFocus?.isConnected&&returnFocus.focus()}
function sessionModal(){openModal('Staff session','Switch roles to explore role-specific interfaces.',`<div class="session-user"><span class="avatar">${initials(roleNames[state.role])}</span><div><strong>${roleNames[state.role]}</strong><p class="small muted">${state.role} · ${state.branch}</p></div></div><form id="role-form">${selectField('Preview staff role','role',Object.keys(permissions),state.role)}</form><p class="info-note">Role selection demonstrates interface access. This prototype does not provide secure authentication.</p>`,`<button class="btn" data-action="reset">Restore sample data</button><button class="btn" data-action="signout">${ic('logout')}Sign out</button><button class="btn primary" form="role-form">Switch role</button>`);$('#role-form').onsubmit=e=>{e.preventDefault();state.role=e.target.elements.role.value;state.page='overview';closeModal();render();toast('Viewing the '+state.role.toLowerCase()+' workspace.')}}
function resetModal(){openModal('Restore sample data','Restart the prototype for another demonstration.','<p class="small muted">This replaces the fictional bookings, records, invoices and transfers saved by this prototype in this browser with the original sample dataset.</p>','<button class="btn" data-action="close">Cancel</button><button class="btn primary" id="reset-confirm">Restore sample data</button>');$('#reset-confirm').onclick=()=>{db=structuredClone(seed);persist();state={...state,page:'overview',patientView:false,branch:branches[0],inventoryBranch:branches[0],date:TODAY,doctor:doctors[0],role:'Manager'};closeModal();render();toast('Original sample data restored.')}}
function renderLogin(){$('#app').innerHTML=`<div class="login-page"><section class="login-art"><div class="brand"><img src="assets/logo.svg" alt="SFC temporary logo"><div><strong>Sunrise</strong><small>Family Clinics</small></div></div><h1>Better connected.<br>Better care.</h1><p>One shared workspace for your patients, your team and every SFC branch.</p><div class="login-caption">CAREBRIDGE TECHNOLOGIES<br>Bridging Care, Building Trust</div></section><main class="login-form"><div class="login-box"><div class="eyebrow">STAFF WORKSPACE</div><h1>Welcome back.</h1><p class="subtitle">Choose a role to explore the clinic prototype.</p><form id="login-form">${selectField('Staff role','role',Object.keys(permissions),state.role)}${selectField('Clinic branch','branch',branches,state.branch)}<button class="btn primary" type="submit">Enter workspace ${ic('arrow')}</button></form><p class="info-note">Assignment prototype with fictional data. Role selection demonstrates navigation; no credentials are needed.</p><button class="text-btn" style="margin-top:20px" data-action="portal">Booking an appointment? Open patient portal →</button></div></main></div>`;bindGlobal();$('#login-form').onsubmit=e=>{e.preventDefault();state.role=e.target.elements.role.value;state.branch=e.target.elements.branch.value;state.inventoryBranch=state.branch;state.loggedIn=true;state.page='overview';render()}}
function renderPortal(){booking={branch:state.branch,doctor:doctors[0],date:TODAY,service:'General practice',time:''};$('#app').innerHTML=`<div class="portal-page"><header class="portal-top"><div class="brand"><img src="assets/logo.svg" alt="SFC temporary logo"><div><strong>Sunrise Family Clinics</strong><small>Here for your family</small></div></div><button class="btn" data-action="staff-return">Staff workspace ${ic('arrow')}</button></header><main class="portal-main"><div class="portal-intro"><div class="eyebrow">YOUR NEXT VISIT, MADE SIMPLE</div><h1>Let’s find a time for you.</h1><p>Choose your clinic, pick an available slot and book your appointment.</p></div><div class="portal-content"><section class="panel"><div class="panel-body"><form id="portal-form"><div class="portal-step"><span class="step-number">1</span>Your appointment</div>${bookingFields(true)}<div class="portal-step" style="margin-top:27px"><span class="step-number">2</span>Your details</div><div class="form-grid">${field('Full name','name','text','',true)}${field('Mobile number','phone','tel','',true)}${field('Email address','email','email','',true,'full')}</div><label class="check-row"><input name="consent" type="checkbox" required>I agree to use these details for this appointment booking.</label><button class="btn primary" style="margin-top:23px;width:100%" type="submit">Confirm appointment ${ic('arrow')}</button></form></div></section><aside class="portal-aside stack"><section class="panel"><div class="panel-body"><div class="alert-icon" style="margin-bottom:17px">${ic('heart')}</div><h3>Care, closer to home.</h3><p>Choose from five SFC branches in Petaling Jaya, Shah Alam and Subang Jaya.</p></div></section><section class="panel"><div class="panel-body"><h3>Before your visit</h3><p>Please arrive 10 minutes before your appointment and bring your identification and panel card, if applicable.</p><p style="margin-top:15px">All appointment times are in Malaysia Time (MYT).</p></div></section><p class="small muted" style="padding:0 8px">Interactive assignment prototype.<br>Use fictional details only.</p></aside></div></main></div>`;bindGlobal();bindBooking($('#portal-form'));$('#portal-form').onsubmit=e=>{e.preventDefault();submitBooking(e.target,true)}}
function renderPortalSuccess(a){$('.portal-main').innerHTML=`<section class="panel" style="max-width:600px;margin:25px auto"><div class="panel-body"><div class="success"><div class="success-mark">${ic('check')}</div><div class="eyebrow">APPOINTMENT CONFIRMED</div><h1>See you soon, ${esc(patient(a.patient).name.split(' ')[0])}.</h1><p style="margin-top:13px">Your booking has been added to the clinic schedule.<br>Keep your booking reference for your visit.</p>${appointmentSummary(a)}<div class="button-row" style="justify-content:center;margin-top:25px"><button class="btn" data-action="portal">Book another appointment</button><button class="btn primary" data-action="staff-return">Return to staff workspace</button></div><p class="info-note">Confirmation preview only. No message has been sent.</p></div></div></section>`;bindGlobal();window.scrollTo(0,0)}
function bindGlobal(){$$('[data-nav]').forEach(b=>b.onclick=()=>{state.patientView=false;nav(b.dataset.nav)});$$('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;({book:()=>bookModal(),register:registerModal,consult:consultModal,transfer:()=>transferModal(),'invoice-new':newInvoice,session:sessionModal,reset:resetModal,close:closeModal,portal:()=>{closeModal();state.portal=true;render()},'staff-return':()=>{state.portal=false;render()},signout:()=>{closeModal();state.loggedIn=false;state.portal=false;render()},'patients-back':()=>{state.patientView=false;render()},'report-export':exportReport,'report-print':()=>window.print(),print:()=>window.print(),menu:()=>$('.sidebar').classList.toggle('open')})[a]?.()});$$('[data-patient]').forEach(b=>b.onclick=()=>{state.patient=b.dataset.patient;state.patientView=true;state.page='patients';render()});$$('[data-book-patient]').forEach(b=>b.onclick=()=>bookModal(b.dataset.bookPatient));$$('[data-book-time]').forEach(b=>b.onclick=()=>bookModal(undefined,b.dataset.bookTime));$$('[data-appointment]').forEach(b=>b.onclick=()=>appointmentDetails(b.dataset.appointment));$$('[data-reminder]').forEach(b=>b.onclick=()=>reminder(b.dataset.reminder));$$('[data-checkin]').forEach(b=>b.onclick=()=>{db.appointments.find(a=>a.id===b.dataset.checkin).status='Checked in';persist();closeModal();render();toast('Patient checked in.')});$$('[data-stock]').forEach(b=>b.onclick=()=>transferModal(b.dataset.stock));$$('[data-stock-tab]').forEach(b=>b.onclick=()=>{state.stockTab=b.dataset.stockTab;render()});$$('[data-billing-tab]').forEach(b=>b.onclick=()=>{state.billingTab=b.dataset.billingTab;render()});$$('[data-day]').forEach(b=>b.onclick=()=>{state.date=b.dataset.day;render()});$$('[data-receive]').forEach(b=>b.onclick=()=>{const t=db.transfers.find(t=>t.id===b.dataset.receive);if(t.status!=='Pending receipt')return;db.stock.find(m=>m.id===t.medicine).qty[branches.indexOf(t.to)]+=t.qty;t.status='Received';persist();render();toast('Receipt confirmed. Destination stock updated.')});$$('[data-invoice]').forEach(b=>b.onclick=()=>invoiceModal(b.dataset.invoice));$$('[data-pay]').forEach(b=>b.onclick=()=>paymentModal(b.dataset.pay));$$('[data-claim-invoice]').forEach(b=>b.onclick=()=>claimForm(b.dataset.claimInvoice));$$('[data-claim]').forEach(b=>b.onclick=()=>claimDetails(b.dataset.claim))}
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const focusable=$$('button:not(:disabled),input:not([type=hidden]),select,textarea,a[href]',$('.modal'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
